import (
	"fmt"
	"time"
)

func startHeartbeat() chan int {
	ch := make(chan int)
	go func() {
		count := 0
		for {
			count++
			ch <- count
			time.Sleep(time.Second)
		}
	}()
	return ch
}

func main() {
	ch := startHeartbeat()
	fmt.Println("started, not reading heartbeats yet")
	time.Sleep(3 * time.Second)
	fmt.Println("first heartbeat:", <-ch)
}

exercises.solutionCode:
package main

import (
	"fmt"
	"time"
)

func startHeartbeat() chan int {
	ch := make(chan int, 1)   // buffered -- sender can complete one send without a waiting receiver
	go func() {
		count := 0
		for {
			count++
			select {
			case ch <- count:
			default:
				// nobody has read the previous heartbeat yet -- drop this one instead of blocking
			}
			time.Sleep(time.Second)
		}
	}()
	return ch
}

func main() {
	ch := startHeartbeat()
	fmt.Println("started, not reading heartbeats yet")
	time.Sleep(3 * time.Second)
	fmt.Println("first heartbeat:", <-ch)
}

sections.body:
Because an unbuffered channel operation is a rendezvous -- both sides must be present -- it's entirely possible to write code where one side is waiting and **nothing will ever arrive to complete the other side**. When this happens across every goroutine in the program simultaneously, the Go runtime detects it and crashes with `fatal error: all goroutines are asleep - deadlock!`, rather than hanging forever silently:

```go
func main() {
	ch := make(chan int)
	ch <- 42   // main blocks here, waiting for a receiver...
	// ...but there is no other goroutine anywhere, so nobody will ever receive.
	fmt.Println(<-ch)
}
// fatal error: all goroutines are asleep - deadlock!
```

This particular deadlock is easy to see: `main` is the only goroutine, and it tries to send on an unbuffered channel before anything could possibly receive -- there is no other goroutine in existence to perform the matching receive. Real-world deadlocks are rarely this obvious; they typically arise from two or more goroutines each waiting on something the other one holds or will produce, or -- very commonly -- a goroutine waiting to send/receive on a channel that some other, still-running goroutine was supposed to service but exited early (due to an error, a `return`, or a `panic`) without ever getting there. Note the important distinction from a goroutine leak: full-program deadlock (**every** goroutine blocked) is detected and crashes the program loudly; a goroutine leak, where only **some** goroutines are stuck while others keep running fine, is invisible to this detector entirely, because the program as a whole is still making progress -- which is precisely why leaks are the more insidious, silent problem of the two.

examples.code:
package main

import (
	"fmt"
	"time"
)

func slowOperation(result chan<- string) {
	time.Sleep(3 * time.Second)
	result <- "done"
}

func main() {
	result := make(chan string)
	go slowOperation(result)

	select {
	case r := <-result:
		fmt.Println("operation finished:", r)
	case <-time.After(1 * time.Second):
		fmt.Println("gave up waiting after 1 second")
	}

package main

import (
	"fmt"
	"sync"
)

func main() {
	done := make(chan struct{})
	var wg sync.WaitGroup

	for i := 0; i < 3; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			<-done   // every one of the 3 goroutines blocks here...
			fmt.Println("worker", id, "released")
		}(i)
	}

	fmt.Println("releasing all workers at once")
	close(done)   // ...and this single close() unblocks all 3 simultaneously
	wg.Wait()

