exercises.solutionCode:
package main

import (
	"fmt"
	"sync"
)

func worker(id int, results chan int, wg *sync.WaitGroup) {
	defer wg.Done()
	results <- id * id
}

func main() {
	results := make(chan int)
	var wg sync.WaitGroup

	for i := 1; i <= 3; i++ {
		wg.Add(1)
		go worker(i, results, &wg)
	}

	go func() {
		wg.Wait()
		close(results)   // closed exactly once, only after all 3 workers have sent
	}()

	var collected []int
	for v := range results {
		collected = append(collected, v)
	}
	fmt.Println(collected)   // e.g. [1 4 9] (order may vary)
}

