package main

import (
	"fmt"
	"sync"
)

func main() {
	var counter int
	var mu sync.Mutex
	var wg sync.WaitGroup

	for i := 0; i < 1000; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			mu.Lock()
			defer mu.Unlock()
			counter++
		}()
	}
	wg.Wait()
	fmt.Println(counter)   // reliably 1000, every single run

package main

import (
	"fmt"
	"sync"
)

func main() {
	var wg sync.WaitGroup
	results := make([]int, 0)
	var mu sync.Mutex

	for i := 0; i < 5; i++ {
		go func(id int) {
			wg.Add(1)   // BUG: Add called inside the goroutine, racing against Wait below
			defer wg.Done()
			mu.Lock()
			results = append(results, id*id)
			mu.Unlock()
		}(i)
	}

	wg.Wait()   // might return immediately if no goroutine has called Add(1) yet
	fmt.Println(len(results))   // unreliable -- sometimes less than 5, varies by run

package main

import (
	"fmt"
	"sync"
)

type SafeCounter struct {
	mu    sync.Mutex
	count int
}

func (c *SafeCounter) Increment() {   // pointer receiver -- required, see below
	c.mu.Lock()
	defer c.mu.Unlock()
	c.count++
}

func main() {
	counter := &SafeCounter{}   // created as a pointer from the start
	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			counter.Increment()   // all 100 goroutines share the SAME SafeCounter, via the pointer
		}()
	}
	wg.Wait()
	fmt.Println(counter.count)   // 100

