package main

import (
	"fmt"
	"sync"
)

func main() {
	scores := make(map[string]int)
	var mu sync.Mutex
	var wg sync.WaitGroup

	names := []string{"Amy", "Ben", "Cara", "Dev", "Ella"}
	for i, name := range names {
		wg.Add(1)
		go func(n string, s int) {
			defer wg.Done()
			mu.Lock()
			defer mu.Unlock()
			scores[n] = s * 10
		}(name, i)
	}

	wg.Wait()
	fmt.Println(scores)   // map[Amy:0 Ben:10 Cara:20 Dev:30 Ella:40]
